using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Threading;using System.Threading.Tasks;using System.Text.RegularExpressions;
public class CodexWakeConfig {
 public bool Enabled,FiveHour,WindowEnabled;public string WindowStart="09:00",WindowEnd="18:00";public bool Weekly=true;public List<string> Attempts=new List<string>();public string LastResult="尚未尝试自动唤醒";public DateTime AttemptedUtc;
 public Dictionary<string,string> PendingEpisodes=new Dictionary<string,string>();public string CandidateAccount="";public DateTime CandidateCheckedUtc;public List<string> CandidateKeys=new List<string>();[ScriptIgnore]public bool Changed;
 internal bool InWindow(DateTime local){if(!WindowEnabled)return true;TimeSpan start,end;if(!TimeSpan.TryParseExact(WindowStart??"",@"hh\:mm",System.Globalization.CultureInfo.InvariantCulture,out start)||!TimeSpan.TryParseExact(WindowEnd??"",@"hh\:mm",System.Globalization.CultureInfo.InvariantCulture,out end)||start==end)return false;var t=local.TimeOfDay;return start<end?t>=start&&t<end:t>=start||t<end;}
 internal static bool AnchoredCycle(CodexQuotaSnapshot current,CodexQuotaSnapshot previous,int minutes){if(current==null||previous==null||current.CheckedUtc-previous.CheckedUtc<TimeSpan.FromSeconds(30))return false;var w=current.Windows.FirstOrDefault(x=>x.Minutes==minutes);var old=previous.Windows.FirstOrDefault(x=>x.Minutes==minutes);return w!=null&&old!=null&&w.ResetUtc>current.CheckedUtc&&old.ResetUtc>previous.CheckedUtc&&Math.Abs((w.ResetUtc-old.ResetUtc).TotalSeconds)<=5;}
 public string Reserve(CodexQuotaSnapshot s,CodexQuotaSnapshot previous,DateTime now,IEnumerable<CodexQuotaReset> history=null){
  Changed=false;if(!Enabled||s==null||previous==null||s.Windows.Any(w=>w.Remaining<=0)||s.RequiresAuthorization||String.IsNullOrEmpty(s.AccountKey)||s.AccountKey!=previous.AccountKey||String.IsNullOrEmpty(s.PlanType)||s.CheckedUtc<=previous.CheckedUtc||now<s.CheckedUtc||now-s.CheckedUtc>TimeSpan.FromMinutes(2))return null;
  if(Attempts==null)Attempts=new List<string>();if(CandidateKeys==null)CandidateKeys=new List<string>();if(PendingEpisodes==null)PendingEpisodes=new Dictionary<string,string>();foreach(var window in s.Windows)if(!window.PendingStart(now)&&PendingEpisodes.Remove(s.AccountKey+":"+window.Minutes+":"))Changed=true;
  if(CandidateKeys.Count>0){bool valid=CandidateAccount==s.AccountKey&&s.CheckedUtc>=CandidateCheckedUtc&&s.CheckedUtc-CandidateCheckedUtc<=TimeSpan.FromMinutes(10)&&CandidateKeys.All(key=>s.Windows.Any(w=>key.StartsWith(s.AccountKey+":"+w.Minutes+":")&&w.PendingStart(now)&&!AnchoredCycle(s,previous,w.Minutes)&&(w.Minutes==300?FiveHour:Weekly)));if(valid&&s.CheckedUtc-CandidateCheckedUtc<TimeSpan.FromSeconds(30))return null;if(valid){var keys=CandidateKeys.Where(k=>!Attempts.Contains(k)).ToArray();Attempts.AddRange(keys);Attempts=Attempts.Skip(Math.Max(0,Attempts.Count-100)).ToList();CandidateKeys.Clear();AttemptedUtc=now;LastResult="两次官方核验周期待启动；已记录本周期唯一尝试";Changed=true;return keys.Length==0?null:String.Join("|",keys);}CandidateKeys.Clear();Changed=true;}
  var pending=new List<string>();foreach(var w in s.Windows){if(w.Minutes==300&&!FiveHour||w.Minutes==10080&&!Weekly||!w.PendingStart(now))continue;var old=previous.Windows.FirstOrDefault(x=>x.Minutes==w.Minutes);if(old==null||AnchoredCycle(s,previous,w.Minutes))continue;string prefix=s.AccountKey+":"+w.Minutes+":";string key;if(!old.PendingStart(previous.CheckedUtc)&&old.ResetUtc!=default(DateTime))key=prefix+old.ResetUtc.Ticks;else if(!PendingEpisodes.TryGetValue(prefix,out key)){var newer=(history??new CodexQuotaReset[0]).Where(e=>e!=null&&e.Minutes==w.Minutes&&e.ObservedUtc>AttemptedUtc&&e.ObservedUtc<=previous.CheckedUtc&&e.ObservedUtc<=now).OrderByDescending(e=>e.ObservedUtc).FirstOrDefault();key=newer!=null?prefix+"observed:"+newer.ObservedUtc.Ticks:Attempts.LastOrDefault(x=>x.StartsWith(prefix))??prefix+"pending:"+s.CheckedUtc.Ticks;}if(!PendingEpisodes.ContainsKey(prefix)||PendingEpisodes[prefix]!=key){PendingEpisodes[prefix]=key;Changed=true;}if(!Attempts.Contains(key))pending.Add(key);}
  if(pending.Count>0){CandidateKeys=pending;CandidateAccount=s.AccountKey;CandidateCheckedUtc=s.CheckedUtc;LastResult="首次核验周期待启动，等待下一次官方核验后再尝试";Changed=true;}return null;
 }

}
public sealed partial class CodexQuotaReader {
 internal static string AccountPlan(object result){var root=result as Dictionary<string,object>;object value;var account=root!=null&&root.TryGetValue("account",out value)?value as Dictionary<string,object>:null;object type,plan;if(account==null||!account.TryGetValue("type",out type)||Convert.ToString(type)!="chatgpt")return "";return account.TryGetValue("planType",out plan)?Convert.ToString(plan):"";}
 public void MaybeWake(CodexQuotaSnapshot s,CodexQuotaConfig cfg,DateTime now,Action persist){
  if(ownedProcesses.IsStopped||!cfg.Enabled||!cfg.BackgroundRefresh||cfg.Wake==null||!cfg.Wake.InWindow(DateTime.Now)||Environment.GetEnvironmentVariable("CONAN_PET_TEST_MODE")=="1"||Interlocked.CompareExchange(ref busy,1,0)!=0)return;
  string reservation=null;try{reservation=cfg.Wake.Reserve(s,cfg.LastObserved,now,cfg.ResetHistory);if(cfg.Wake.Changed)persist();if(reservation==null){Interlocked.Exchange(ref busy,0);return;}}catch{Interlocked.Exchange(ref busy,0);throw;}
  string account=s.AccountKey,exe=cfg.Executable,home=cfg.Home,attempt=Guid.NewGuid().ToString("N"),windows=QuotaAudit.WindowNames(reservation);
  if(Audit==null||!Audit.Add(new QuotaAuditEvent{Utc=DateTime.UtcNow,Kind="wake-reserved",Attempt=attempt,Windows=windows,Method="两次官方额度查询",Result="已预约一次唤醒，尚未发送模型请求",RequestStarted=false})){lock(gate){cfg.Wake.LastResult="本地记录不可写，已跳过自动唤醒";Dirty=true;}Interlocked.Exchange(ref busy,0);return;}
  Task.Run(()=>{string result="本次唤醒未完成";string modelName="";bool sent=false;WakeUsage usage=null;try{if(!cfg.Wake.Enabled||!cfg.Enabled||!cfg.BackgroundRefresh)result="相关开关已关闭，已取消本次尝试";else if(Trust==null)result="额度程序未授权，本次未发送";else using(var permit=Trust.OpenVerified(exe,home)){var verified=Fetch(permit.Identity.Executable,permit.Identity.Home,ownedProcesses);if(verified.AccountKey!=account||String.IsNullOrEmpty(verified.PlanType))throw new IOException("账户已变化或不是ChatGPT订阅登录，本次未发送");if(!ReservationPending(reservation,verified,cfg,DateTime.UtcNow))result="本次预约的额度周期已启动或相应开关关闭，无需唤醒";else {var model=LightModel(permit.Identity.Executable,permit.Identity.Home,ownedProcesses);modelName=model.Item1;verified=Fetch(permit.Identity.Executable,permit.Identity.Home,ownedProcesses);if(verified.AccountKey!=account||!ReservationPending(reservation,verified,cfg,DateTime.UtcNow))result="发送前复核：预约周期已启动或相应开关关闭，未发送";else if(!Audit.Add(new QuotaAuditEvent{Utc=DateTime.UtcNow,Kind="wake-ready",Attempt=attempt,Windows=windows,Method="官方 Codex CLI 临时会话",Result="复核通过，准备发送一次最小请求",Model=modelName,RequestStarted=false}))result="本地记录不可写，已跳过自动唤醒";else {result=RunMinimalRequest(permit.Identity.Executable,permit.Identity.Home,model.Item1,model.Item2,ownedProcesses,out sent,out usage);try{var after=Fetch(permit.Identity.Executable,permit.Identity.Home,ownedProcesses);string detail=after.AccountKey!=account?"账户已变化，无法确认":String.Join("；",after.Windows.Where(w=>reservation.Contains(":"+w.Minutes+":")).Select(w=>(w.Minutes==300?"五小时":"周额度")+" 剩余 "+w.Remaining.ToString("F1")+"%，官方重置时间 "+(w.ResetUtc==default(DateTime)?"未提供":w.ResetUtc.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"))+"；"+(w.PendingStart(after.CheckedUtc)?"是否启动仍需后续核验":"已取得未来重置时间，是否由本次请求触发无法确认")).ToArray());if(String.IsNullOrEmpty(detail))detail="官方未返回目标窗口，无法确认";Audit.Add(new QuotaAuditEvent{Utc=DateTime.UtcNow,Kind="wake-verification",Attempt=attempt,Windows=windows,Method="请求后官方额度查询",Result=detail,RequestStarted=sent});}catch(Exception ex){Audit.Add(new QuotaAuditEvent{Utc=DateTime.UtcNow,Kind="wake-verification",Attempt=attempt,Windows=windows,Method="请求后官方额度查询",Result="复查失败，无法确认："+WakeErrorText(ex.Message),RequestStarted=sent});}}}}}catch(Exception e){result="本次唤醒未完成："+WakeErrorText(e.Message)+"；本周期不再自动尝试。";}finally{Audit.Add(new QuotaAuditEvent{Utc=DateTime.UtcNow,Kind="wake-result",Attempt=attempt,Windows=windows,Method="官方 Codex CLI 临时会话",Result=WakeErrorText(result),Model=modelName,RequestStarted=sent,InputTokens=usage==null?null:usage.Input,CachedTokens=usage==null?null:usage.Cached,OutputTokens=usage==null?null:usage.Output});lock(gate){cfg.Wake.LastResult=result;Dirty=true;}RefreshNow();Interlocked.Exchange(ref busy,0);if(!ownedProcesses.IsStopped&&sent&&cfg.PhoneWakeNotify&&Phone!=null){string body="时间："+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+"\n\n窗口："+windows+"\n\n最小请求进程已启动；"+(result.Contains("已完成一次最小请求")?"CLI 报告完成":"结果未确认，请查看电脑本地记录")+"。官方额度周期仍需后续核验。";if(usage!=null&&usage.Input.HasValue)body+="\n\n输入 token："+usage.Input+"，输出 token："+(usage.Output.HasValue?usage.Output.ToString():"未知");string phoneResult=Phone.Send("柯南 · Codex 额度唤醒",body);Audit.Add(new QuotaAuditEvent{Utc=DateTime.UtcNow,Kind="phone-result",Attempt=attempt,Windows=windows,Method="Server酱微信推送",Result=phoneResult});}}});
 }
 internal static bool ReservationPending(string reservation,CodexQuotaSnapshot snapshot,CodexQuotaConfig cfg,DateTime now){if(cfg==null||cfg.Wake==null||!cfg.Enabled||!cfg.BackgroundRefresh||!cfg.Wake.Enabled||!cfg.Wake.InWindow(now.ToLocalTime())||snapshot==null||snapshot.Windows.Any(w=>w.Remaining<=0)||snapshot.RequiresAuthorization||String.IsNullOrEmpty(snapshot.AccountKey)||String.IsNullOrEmpty(snapshot.PlanType)||snapshot.CheckedUtc>now||now-snapshot.CheckedUtc>TimeSpan.FromMinutes(2))return false;return (reservation??"").Split('|').Any(key=>snapshot.Windows.Any(w=>key.StartsWith(snapshot.AccountKey+":"+w.Minutes+":",StringComparison.Ordinal)&&(w.Minutes==300?cfg.Wake.FiveHour:w.Minutes==10080&&cfg.Wake.Weekly)&&w.PendingStart(now)));}
 public class WakeUsage {public long? Input,Cached,Output;}
 internal static WakeUsage ParseWakeUsage(string output){var json=new JavaScriptSerializer();foreach(string line in (output??"").Split('\n'))try{var row=json.Deserialize<Dictionary<string,object>>(line);object kind,value;if(row==null||!row.TryGetValue("type",out kind)||Convert.ToString(kind)!="turn.completed"||!row.TryGetValue("usage",out value))continue;var usage=value as Dictionary<string,object>;if(usage==null)return null;var result=new WakeUsage();long n;if(usage.TryGetValue("input_tokens",out value)&&Int64.TryParse(Convert.ToString(value),out n)&&n>=0)result.Input=n;if(usage.TryGetValue("cached_input_tokens",out value)&&Int64.TryParse(Convert.ToString(value),out n)&&n>=0)result.Cached=n;if(usage.TryGetValue("output_tokens",out value)&&Int64.TryParse(Convert.ToString(value),out n)&&n>=0)result.Output=n;return result.Input.HasValue||result.Output.HasValue?result:null;}catch(ArgumentException){}catch(InvalidOperationException){}return null;}

 internal static Tuple<string,string> LightModel(string exe,string home,OwnedProcesses owned=null){
  var info=new ProcessStartInfo(exe,"app-server --listen stdio://"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["CODEX_HOME"]=CodexQuotaHome.Prepare(home);
  using(var p=owned==null?Process.Start(info):owned.Start(info)){try{p.StandardError.ReadToEndAsync();var json=new JavaScriptSerializer();Action<object> send=value=>{p.StandardInput.WriteLine(json.Serialize(value));p.StandardInput.Flush();};send(new{id=1,method="initialize",@params=new{clientInfo=new{name="conan-quota-models",version="5.30.6"}}});var until=DateTime.UtcNow.AddSeconds(15);while(DateTime.UtcNow<until){var read=p.StandardOutput.ReadLineAsync();if(!read.Wait(Math.Max(1,(int)(until-DateTime.UtcNow).TotalMilliseconds))||read.Result==null)break;var d=json.Deserialize<Dictionary<string,object>>(read.Result);object id;if(!d.TryGetValue("id",out id))continue;if(d.ContainsKey("error"))throw new IOException("模型列表不可用");if(Convert.ToInt32(id)==1){send(new{method="initialized",@params=new{}});send(new{id=2,method="model/list",@params=new{limit=100}});}else if(Convert.ToInt32(id)==2){var r=(Dictionary<string,object>)d["result"];var data=(System.Collections.IEnumerable)r["data"];foreach(Dictionary<string,object> model in data){string name=Convert.ToString(model["model"]);object hidden;if(model.TryGetValue("hidden",out hidden)&&Convert.ToBoolean(hidden))continue;if(!name.Contains("mini")&&!name.Contains("luna"))continue;string effort=null;object options;if(model.TryGetValue("supportedReasoningEfforts",out options))foreach(Dictionary<string,object> option in (System.Collections.IEnumerable)options){string e=Convert.ToString(option["reasoningEffort"]);if(e=="none"||e=="minimal"||e=="low"){effort=e;break;}}if(effort!=null)return Tuple.Create(name,effort);}throw new IOException("没有可用的轻量模型，已跳过；不会回退到高成本模型");}}throw new IOException("读取模型列表超时");}finally{try{CloseOwnedServer(p);}finally{if(owned!=null)owned.Forget(p);}}}
 }
 internal static string MinimalArguments(string model,string effort,string directory){
  if(String.IsNullOrEmpty(model)||model.Any(c=>!Char.IsLetterOrDigit(c)&&c!='-'&&c!='.'&&c!='_')||!new[]{"none","minimal","low"}.Contains(effort))throw new ArgumentException("无效的轻量模型参数");
  // Built-in provider IDs are reserved; model_providers.openai overrides abort startup.
  return "exec --json --color never --ignore-user-config --ignore-rules --ephemeral --skip-git-repo-check --sandbox read-only --model "+model+" -c approval_policy=\"never\" -c web_search=\"disabled\" -c model_reasoning_effort=\""+effort+"\" -c model_reasoning_summary=\"none\" -c notify=[] --disable unbounded_connection_retries -c project_doc_max_bytes=0 -c skills.max_context_tokens=1 --disable shell_tool --disable unified_exec --disable plugins --disable apps --disable hooks --disable multi_agent --disable browser_use --disable computer_use --disable image_generation --disable code_mode --disable code_mode_host --disable view_image --cd \""+directory+"\" \"Reply only OK. Do not use tools.\"";
 }
 internal static string WakeProcessResult(int exitCode,string output,string error,string model){
  string terminal="",detail="";var json=new JavaScriptSerializer();
  foreach(string line in (output??"").Split('\n'))try{var row=json.Deserialize<Dictionary<string,object>>(line);object kind,value;if(row==null||!row.TryGetValue("type",out kind))continue;string type=Convert.ToString(kind);if(type=="turn.completed")terminal="completed";if(type=="turn.failed"){terminal="failed";var failure=row.TryGetValue("error",out value)?value as Dictionary<string,object>:null;if(failure!=null&&failure.TryGetValue("message",out value))detail=Convert.ToString(value);}else if(type=="error"&&row.TryGetValue("message",out value))detail=Convert.ToString(value);}catch(ArgumentException){}catch(InvalidOperationException){}
  if(exitCode==0&&terminal=="completed")return "已完成一次最小请求（"+model+"）；新周期以随后官方核验为准。";
  if(String.IsNullOrWhiteSpace(detail)){var lines=(error??"").Split('\n').Select(x=>x.Trim()).Where(x=>x.Length>0);detail=lines.FirstOrDefault(x=>x.StartsWith("Error",StringComparison.OrdinalIgnoreCase))??lines.LastOrDefault();}
  if(String.IsNullOrWhiteSpace(detail))detail=exitCode==0?"CLI没有返回请求完成事件":"CLI没有返回具体错误";
  return "最小请求未完成（退出码 "+exitCode+"，模型 "+model+"）："+WakeErrorText(detail)+"；本周期不再自动尝试。";
 }
 internal static string WakeErrorText(string text){
  text=Regex.Replace(text??"",@"(?i)Bearer\s+[^\s""']+","Bearer [已隐藏]");
  text=Regex.Replace(text,@"\bsk-[A-Za-z0-9_-]+","[密钥已隐藏]");
  text=Regex.Replace(text,@"(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b","[邮箱已隐藏]");
  text=Regex.Replace(text,@"(?i)\b[A-Z]:\\[^\r\n""<>|]*","[本机路径已隐藏]");
  text=Regex.Replace(text,@"\s+"," ").Trim();return text.Length>360?text.Substring(0,360)+"…":text;
 }
 static string RunMinimalRequest(string exe,string home,string model,string effort,OwnedProcesses owned,out bool sent,out WakeUsage usage){
  sent=false;usage=null;
  string directory=Path.Combine(Path.GetTempPath(),"conan-quota-wake-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);
  try{var info=new ProcessStartInfo(exe,MinimalArguments(model,effort,directory)){WorkingDirectory=directory,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["CODEX_HOME"]=CodexQuotaHome.Prepare(home);foreach(string name in new[]{"OPENAI_API_KEY","OPENAI_BASE_URL","AZURE_OPENAI_API_KEY","CODEX_API_KEY"})info.EnvironmentVariables.Remove(name);
   using(var p=owned.Start(info)){try{sent=true;p.StandardInput.Close();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(45000)){p.Kill();return "最小请求超时，本周期不再自动尝试；请核对官方额度。";}Task.WaitAll(new Task[]{output,error},2000);string stdout=output.Status==TaskStatus.RanToCompletion?output.Result:"";usage=ParseWakeUsage(stdout);return WakeProcessResult(p.ExitCode,stdout,error.Status==TaskStatus.RanToCompletion?error.Result:"",model);}finally{try{CloseOwnedServer(p);}finally{owned.Forget(p);}}}
  }finally{try{Directory.Delete(directory,true);}catch(IOException){}catch(UnauthorizedAccessException){}}
 }
}
